import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useSheetToday } from '../sheet/useSheetToday';
import { peopleKey, peopleQuery } from './peopleQuery';
import { useGrades } from '../grades/gradesQuery';
import type { Grade, Person } from './peopleQuery';
import { useSelectedPeople } from './useSelectedPeople';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Gives every ticked person a grade from a from-date (blank: the sheet's today), one at a time in list
 * order, through the same edit the person form saves, so each writes the same audit lines. A person the
 * server refuses is left as they were and not counted.
 */
function BulkGrade({ user, sheetId }: { user: string; sheetId: string }) {
  const queryClient = useQueryClient();
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const sheetGrades = useGrades(sheetId);
  const today = useSheetToday(sheetId);
  const [selected, setSelected] = useSelectedPeople();
  const [grade, setGrade] = useState<Grade>('A');
  const [from, setFrom] = useState('');
  const [error, setError] = useState('');
  const [graded, setGraded] = useState<number | undefined>();
  const once = useSubmitOnce();

  const apply = useMutation({
    mutationFn: async (targets: Person[]): Promise<number> => {
      let changed = 0;
      for (const p of targets) {
        try {
          await putJson<Person>(
            `/api/sheets/${encodeURIComponent(sheetId)}/people/${p.id}`,
            { name: p.name, grade, gradeFrom: from.trim(), terms: p.terms == null ? '' : String(p.terms), contact: p.contact ?? '', tags: p.tags.join(',') },
            user,
          );
          changed++;
        } catch {
          // refused: left as they were
        }
      }
      return changed;
    },
    onSuccess: async (n) => {
      setSelected([]);
      setFrom('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      setGraded(n);
    },
    onError: () => setError('The grades could not be given.'),
  });

  return (
    <section data-testid="bulk-grade-panel">
      <select
        data-testid="bulk-grade"
        value={grade}
        onChange={(e) => {
          setGrade(e.target.value as Grade);
          setError('');
        }}
      >
        {sheetGrades.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>{' '}
      <input
        data-testid="bulk-grade-from"
        placeholder={today || 'from yyyy-mm-dd'}
        value={from}
        onChange={(e) => {
          setFrom(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="bulk-grade-apply"
        disabled={apply.isPending}
        onClick={() => {
          setError('');
          setGraded(undefined);
          const f = from.trim();
          if (f !== '' && !DATE.test(f)) {
            setError('The date must be yyyy-mm-dd.');
            return;
          }
          // In list order, whatever order they were ticked in.
          once(() => apply.mutateAsync(people.filter((p) => selected.includes(p.id))));
        }}
      >
        Grade selected
      </button>
      {graded !== undefined && (
        <>
          {' '}
          Changed <span data-testid="bulk-graded">{graded}</span>
        </>
      )}
      {error && <span data-testid="person-error">{error}</span>}
    </section>
  );
}

export const contribution = SheetPanel.fill({
  order: 12,
  Component: ({ user, sheetId }) => <BulkGrade key={sheetId} user={user} sheetId={sheetId} />,
});
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { peopleKey, peopleQuery } from './peopleQuery';
import type { Person } from './peopleQuery';
import { ColumnShown } from './useColumns';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Whether the person has any hold, their holds, and the control that adds one from a from-date (blank: the
 * sheet's today) to an optional to-date. Their OPEN claims dated within a hold, unless bound by a statement,
 * count in no live total; a hold ends on its to-date.
 */
function PersonHold({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const person = (useQuery(peopleQuery(sheetId)).data ?? []).find((p) => p.id === personId);
  const hold = useMutation({
    mutationFn: (body: { from: string; to: string }) =>
      putJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/hold`, body, user),
    onSuccess: async () => {
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('The hold could not be added.'),
  });

  return (
    <td>
      <span data-testid="person-hold">{person?.held ? 'yes' : 'no'}</span>{' '}
      {(person?.holds ?? []).map((h, i) => (
        <span key={i} data-testid="person-hold-line">
          {h.from} to {h.to ?? '…'}{' '}
        </span>
      ))}
      <input
        data-testid="person-hold-from"
        placeholder="from yyyy-mm-dd"
        value={from}
        onChange={(e) => {
          setFrom(e.target.value);
          setError('');
        }}
      />{' '}
      <input
        data-testid="person-hold-to"
        placeholder="to yyyy-mm-dd"
        value={to}
        onChange={(e) => {
          setTo(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-hold-toggle"
        disabled={hold.isPending}
        onClick={() => {
          setError('');
          const f = from.trim();
          const t = to.trim();
          if ((f !== '' && !DATE.test(f)) || (t !== '' && !DATE.test(t))) {
            setError('The dates must be yyyy-mm-dd.');
            return;
          }
          if (f !== '' && t !== '' && t < f) {
            setError('The to-date is before the from-date.');
            return;
          }
          once(() => hold.mutateAsync({ from: f, to: t }));
        }}
      >
        Hold
      </button>
      {error && <span data-testid="person-error">{error}</span>}
    </td>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 19, Component: () => <ColumnShown column="hold"><th>Hold</th></ColumnShown> }),
  PersonCells.fill({ order: 19, Component: (ctx) => <ColumnShown column="hold"><PersonHold {...ctx} /></ColumnShown> }),
];
